public class ExternalCallNode : CallNode {

	private static readonly Icon EXTERNAL_ICON = new GIcon("icon.plugin.calltree.node.external");
	private static readonly Icon CALL_REFERENCE_ICON = createIcon(EXTERNAL_ICON, true);
	private static readonly Icon NON_CALL_REFERENCE_ICON = createIcon(EXTERNAL_ICON, false);

	private Function function;
	private Address sourceAddress;
	private string name;

	ExternalCallNode(Function function, Address sourceAddress,
			bool isCallReference, CallTreeOptions callTreeOptions) : base(callTreeOptions)
    {
		this.function = function;
		this.sourceAddress = sourceAddress;
		this.name = function.getName();
		this.isCallReference = isCallReference;
	}

	/* @Override */
	public int loadAll(TaskMonitor monitor)
    {
		return 1; // this node cannot be opened
	}

	/* @Override */
	CallNode recreate() {
		return new ExternalCallNode(function, sourceAddress, isCallReference, callTreeOptions);
	}

	/* @Override */
	public Function getRemoteFunction() {
		return function;
	}

	/* @Override */
	public ProgramLocation getLocation() {
		return new FunctionSignatureFieldLocation(function.getProgram(), function.getEntryPoint());
	}

	/* @Override */
	public Address getSourceAddress() {
		return sourceAddress;
	}

	/* @Override */
	public List<GTreeNode> generateChildren(TaskMonitor monitor)
    {
		return new();
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		return isCallReference ? CALL_REFERENCE_ICON : NON_CALL_REFERENCE_ICON;
	}

	/* @Override */
	public string getName() {
		return name;
	}

	/* @Override */
